window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c88666f7cf08b202"]={"versions": [{"id": "FIG-c88666f7cf08b202", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation eines algorithmischen Kontrollflusses.</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Komponente der AUTOSAR E2E-Library (<code>E2E</code>), angesiedelt in den AUTOSAR Foundation / Classic Platform Services bzw. Adaptive Platform Functional Clusters (<code>ara::com</code> / E2E-Protection).</li>\n<li>Spezifiziert den Teilschritt „Read SourceID“ innerhalb der Empfänger-Prüffunktion <code>E2E_PXXmSinkCheck()</code>.</li>\n<li><code>XX</code> fungiert als Platzhalter für methodenspezifische E2E-Profile (z. B. Profile 04m, 07m, 22m) zur Absicherung von Client/Server- und RPC-Kommunikationsmustern (Method Communication, typisch im Kontext von SOME/IP und Service-orientierten Architekturen).</li>\n<li>Funktionaler Zweck: Extrahieren der Quellkennung (<code>SourceID</code> / <code>MessageID</code>) aus dem empfangenen Rohdaten-Bytestream (<code>Data</code>), um nachfolgend Mehrfachsender bzw. Client-Instanzen in 1:n-Kommunikationsbeziehungen fehlerfrei zu identifizieren und zu validieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Funktionskontext:</strong></li>\n<li><code>E2E_PXXmSinkCheck()</code>: E2E-Prüfroutine auf Senken-/Empfängerseite (Method Sink).</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>Data</code>: Eingehender Bytestring / Serialisierte Payload inklusive E2E-Header (<code>uint8*</code>).</li>\n<li><code>ReceivedSourceID</code>: Lokale Variable (Typ <code>uint32</code>), die den extrahierten Identifikator aufnimmt.</li>\n<li><code>Offset</code>: Konfigurierter Basis-Byte-Offset des E2E-Headers innerhalb der PDU/Payload (<code>Config-&gt;Offset</code>).</li>\n<li><code>PXXMESSAGE_POS</code>: Profilspezifische relative Byte-Position des <code>MessageID</code>-Feldes im E2E-Header.</li>\n<li><strong>Stereotypen & Spezifikationsanker:</strong></li>\n<li>Anforderung <code>[PRS_E2E_01197]</code>, abgeleitet aus <code>[RS_E2E_08539]</code>.</li>\n<li>Stereotyp-Klassifikation: Normativer Verhaltensstandard für profilbasierte Algorithmen (Method Profile Template).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Sub-Ablauf „Read SourceID“ innerhalb von <code>E2E_PXXmSinkCheck()</code>.</li>\n<li><strong>Aktion „Copy MessageID“:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Quellbereich:</strong> 4 aufeinanderfolgende Bytes im PDU-Array von <code>Offset + PXXMESSAGE_POS</code> bis <code>Offset + PXXMESSAGE_POS + 3</code>.</li>\n<li><strong>Bitbreite & Maskierung:</strong> <code>MessageID</code> umfasst exakt 28 Bits. Es werden die 28 niederwertigsten Bits (least significant bits) extrahiert; die oberen 4 Bits des 32-Bit-Wortes werden ignoriert bzw. ausmaskiert.</li>\n<li><strong>Bytereihenfolge:</strong> Serialisierung im Bytestream liegt in <strong>Big-Endian</strong>-Order (Network Byte Order) vor und wird entsprechend endianness-konform in die lokale 32-Bit-Variable <code>ReceivedSourceID</code> überführt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Activity Final Node:</strong> Terminierung des Extraktionsschritts; Übergabe von <code>ReceivedSourceID</code> an den nachgelagerten Prüfschritt (Vergleich gegen erwartete Quell-IDs).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Byte- und Bit-Handling (Bit-Packing):</strong></li>\n<li>Entwickler müssen sicherstellen, dass bei der 28-Bit-Extraktion über eine 4-Byte-Grenze keine Host-Endianness-Fehler auftreten. Auf Little-Endian-Mikrocontrollern (z. B. ARM Cortex-R/M, TriCore) ist zwingend ein Byte-Swap (<code>REV</code>/<code>__builtin_bswap32</code>) bzw. schiebe- und maskierungsbasierte Rekonstruktion (<code>uint32</code>) anzuwenden.</li>\n<li>Bitmaske: <code>ReceivedSourceID = (RawWord32BigEndian) &amp; 0x0FFFFFFFu</code>.</li>\n<li><strong>Speicherzugriff & Alignment:</strong></li>\n<li>Der Offset <code>Offset + PXXMESSAGE_POS</code> ist im Bytestrom nicht zwingend 32-Bit-aligned. Ein direkter Cast auf <code>uint32*</code> führt auf Architekturen mit Alignment-Faults (z. B. ältere ARM-Cores) zu Laufzeit-Exceptions. Die Extraktion muss daher byte-weise erfolgen.</li>\n<li><strong>PDU-Längenprüfung (Precondition):</strong></li>\n<li>Vor Ausführung dieses Schritts muss die PDU-Länge gegen <code>Offset + PXXMESSAGE_POS + 4</code> validiert sein (<code>Length Check</code>), um Pufferüberläufe (Buffer Over-Read) bei korrumpierten oder zu kurzen Nachrichten zu verhindern.</li>\n</ul>"}, {"id": "FIG-418d4172881a8a07", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (UML Activity Diagram) zur Spezifikation eines algorithmischen Kontrollflusses.</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li>Komponente der AUTOSAR E2E-Library (<code>E2E</code>), angesiedelt in den AUTOSAR Foundation / Classic Platform Services bzw. Adaptive Platform Functional Clusters (<code>ara::com</code> / E2E-Protection).</li>\n<li>Spezifiziert den Teilschritt „Read SourceID“ innerhalb der Empfänger-Prüffunktion <code>E2E_PXXmSinkCheck()</code>.</li>\n<li><code>XX</code> fungiert als Platzhalter für methodenspezifische E2E-Profile (z. B. Profile 04m, 07m, 22m) zur Absicherung von Client/Server- und RPC-Kommunikationsmustern (Method Communication, typisch im Kontext von SOME/IP und Service-orientierten Architekturen).</li>\n<li>Funktionaler Zweck: Extrahieren der Quellkennung (<code>SourceID</code> / <code>MessageID</code>) aus dem empfangenen Rohdaten-Bytestream (<code>Data</code>), um nachfolgend Mehrfachsender bzw. Client-Instanzen in 1:n-Kommunikationsbeziehungen fehlerfrei zu identifizieren und zu validieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Funktionskontext:</strong></li>\n<li><code>E2E_PXXmSinkCheck()</code>: E2E-Prüfroutine auf Senken-/Empfängerseite (Method Sink).</li>\n<li><strong>Datenstrukturen & Variablen:</strong></li>\n<li><code>Data</code>: Eingehender Bytestring / Serialisierte Payload inklusive E2E-Header (<code>uint8*</code>).</li>\n<li><code>ReceivedSourceID</code>: Lokale Variable (Typ <code>uint32</code>), die den extrahierten Identifikator aufnimmt.</li>\n<li><code>Offset</code>: Konfigurierter Basis-Byte-Offset des E2E-Headers innerhalb der PDU/Payload (<code>Config-&gt;Offset</code>).</li>\n<li><code>PXXMESSAGE_POS</code>: Profilspezifische relative Byte-Position des <code>MessageID</code>-Feldes im E2E-Header.</li>\n<li><strong>Stereotypen & Spezifikationsanker:</strong></li>\n<li>Anforderung <code>[PRS_E2E_01197]</code>, abgeleitet aus <code>[RS_E2E_08539]</code>.</li>\n<li>Stereotyp-Klassifikation: Normativer Verhaltensstandard für profilbasierte Algorithmen (Method Profile Template).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Sub-Ablauf „Read SourceID“ innerhalb von <code>E2E_PXXmSinkCheck()</code>.</li>\n<li><strong>Aktion „Copy MessageID“:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Quellbereich:</strong> 4 aufeinanderfolgende Bytes im PDU-Array von <code>Offset + PXXMESSAGE_POS</code> bis <code>Offset + PXXMESSAGE_POS + 3</code>.</li>\n<li><strong>Bitbreite & Maskierung:</strong> <code>MessageID</code> umfasst exakt 28 Bits. Es werden die 28 niederwertigsten Bits (least significant bits) extrahiert; die oberen 4 Bits des 32-Bit-Wortes werden ignoriert bzw. ausmaskiert.</li>\n<li><strong>Bytereihenfolge:</strong> Serialisierung im Bytestream liegt in <strong>Big-Endian</strong>-Order (Network Byte Order) vor und wird entsprechend endianness-konform in die lokale 32-Bit-Variable <code>ReceivedSourceID</code> überführt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Activity Final Node:</strong> Terminierung des Extraktionsschritts; Übergabe von <code>ReceivedSourceID</code> an den nachgelagerten Prüfschritt (Vergleich gegen erwartete Quell-IDs).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Byte- und Bit-Handling (Bit-Packing):</strong></li>\n<li>Entwickler müssen sicherstellen, dass bei der 28-Bit-Extraktion über eine 4-Byte-Grenze keine Host-Endianness-Fehler auftreten. Auf Little-Endian-Mikrocontrollern (z. B. ARM Cortex-R/M, TriCore) ist zwingend ein Byte-Swap (<code>REV</code>/<code>__builtin_bswap32</code>) bzw. schiebe- und maskierungsbasierte Rekonstruktion (<code>uint32</code>) anzuwenden.</li>\n<li>Bitmaske: <code>ReceivedSourceID = (RawWord32BigEndian) &amp; 0x0FFFFFFFu</code>.</li>\n<li><strong>Speicherzugriff & Alignment:</strong></li>\n<li>Der Offset <code>Offset + PXXMESSAGE_POS</code> ist im Bytestrom nicht zwingend 32-Bit-aligned. Ein direkter Cast auf <code>uint32*</code> führt auf Architekturen mit Alignment-Faults (z. B. ältere ARM-Cores) zu Laufzeit-Exceptions. Die Extraktion muss daher byte-weise erfolgen.</li>\n<li><strong>PDU-Längenprüfung (Precondition):</strong></li>\n<li>Vor Ausführung dieses Schritts muss die PDU-Länge gegen <code>Offset + PXXMESSAGE_POS + 4</code> validiert sein (<code>Length Check</code>), um Pufferüberläufe (Buffer Over-Read) bei korrumpierten oder zu kurzen Nachrichten zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-c88666f7cf08b202", "to": "FIG-418d4172881a8a07", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
